void format(LoggingEvent event){
    // Formatted string to be returned
    String formattedString;

    // Get the conversion pattern for the event
    String conversionPattern = event.getConversionPattern();

    // Initialize the formatted string with the conversion pattern
    formattedString = conversionPattern;

    // Replace placeholders in the conversion pattern with actual values from the event
    formattedString = formattedString.replaceAll("\\(\", city\\)", event.getCity());
    formattedString = formattedString.replaceAll("\\(\", time\\)", event.getTime());
    formattedString = formattedString.replaceAll("\\(\", priority\\)", event.getPriority());
    formattedString = formattedString.replaceAll("\\(\", message\\)", event.getMessage());

    // Return the formatted string
    return formattedString;
}

