void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
  // initialise local variables for vertices and edges
  V[] vertices = new V[numVertices];
  E[] edges = new E[numEdges];

  // create a graphs with no vertices or edges
  Graph graph = new Graph();

  // get the current index in the result map
  int index = resultMap.size();

  // while there are vertices left to be added
  while (numVertices != 0){
    // get the next vertex and index
    V vertex = vertices[index];
    int vertexIndex = index++;

    // add the vertex to the graph
    graph.addVertex(vertex);

    // add edges to vertices that come after this vertex in the current iteration
    for (int i = vertexIndex; i < numVertices; i++){
      E edge = edges[index];
      if (edge != null){
        graph.addEdge(vertex, vertices[i], edge);
      }
    }

    // decrease the number of vertices left to be added
    numVertices--;
  }

  // return the generated graph
  return graph;
}

