public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }

    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i == str.length() - 1) {
                break;
            }
            char next = str.charAt(i + 1);
            if (next == 'n') {
                builder.append('\n');
            } else if (next == 'r') {
                builder.append('\r');
            } else if (next == 't') {
                builder.append('\t');
            } else if (next == 'b') {
                builder.append('\b');
            } else if (next == 'f') {
                builder.append('\f');
            } else if (next == 'u') {
                if (i >= str.length() - 6) {
                    break;
                }
                String hexStr = str.substring(i + 2, i + 6);
                builder.append((char) Integer.parseInt(hexStr, 16));
                i += 4;
            } else {
                builder.append(next);
            }
        } else {
            builder.append(c);
        }
    }

    return builder.toString();
}

