        for (int i = 0; i < str.length(); i++) {
            if (str.charAt(i) == '\\' && i < str.length() - 1) {
                char c = str.charAt(i + 1);
                switch (c) {
                    case 't':
                        output += "\t";
                        break;
                    case 'n':
                        output += "\n";
                        break;
                    case 'r':
                        output += "\r";
                        break;
                    case 'f':
                        output += "\f";
                        break;
                    case '"':
                    case '\'':
                    case '\\':
                    case '/':
                        output += c;
                        break;
                    default:
                        throw new Exception("Illegal escape sequence \\" + c);
                }
                i++;
            } else {
                output += str.charAt(i);
            }
        }
