void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Find the bucket with the minimum label
    Set<Integer> minBucket = bucketsByLabel.stream()
            .filter(bucket -> bucket.size() > 0)
            .min(Comparator.comparingInt(bucket -> bucket.stream()
                    .mapToInt(labels::get)
                    .min()
                    .orElse(Integer.MAX_VALUE)))
            .orElse(null);

    // If the minimum bucket is not empty
    if (minBucket != null) {
        // Set the labels of all vertices in the bucket to 0
        minBucket.forEach(vertex -> labels.set(vertex, 0));
        // Remove all vertices from the bucket
        bucketsByLabel.set(minLabel, new HashSet<>());
    }
}

