ListNodeImpl<E> next = node.next;

if ( prev == null ) {
	if ( next == null ) {
		// Node is only element in the list
		head = tail = null;
	} else {
		// Node is head of the list
		head = next;
		next.prev = null;
	}
} else if ( next == null ) {
	// Node is tail of the list
	tail = prev;
	prev.next = null;
} else {
	// Node is in the middle of the list
	prev.next = next;
	next.prev = prev;
}

node.prev = null;
node.next = null;
size--;
}

