   for (E e : graph.getEdges()) {
      List<Pair<Integer,Integer>> currentSeparator = new ArrayList<>();
      for (E neighbor : graph.getNeighbors(e)) {
         if (graph.isNeighbor(e, neighbor)) {
            currentSeparator.add(new Pair(neighbor, e));
         }
      }
      separatorList.add(new Pair(currentSeparator, e));
   }
   return separatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.getEdges()) {
        List<Pair<Integer, Integer>> separatorList = new ArrayList<>();
        separatorList.addAll(computeLocalSeparatorList(e, 0));
        globalSeparatorList.add(Pair.of(separatorList, e));
    }
    return globalSeparatorList;
}

private List<Pair<Integer, Integer>> computeLocalSeparatorList(E edge, int edgeIndex) {
    List<Pair<Integer, Integer>> separatorList = new ArrayList<>();
    separatorList.add(Pair.of(edgeIndex, edgeIndex + 1));
    for (Pair<Integer, Integer> edgePair : graph.getNeighbors(edge)) {
        if (edgePair.getValue() != edgeIndex) {
            separatorList.add(Pair.of(edgePair.getKey(), edgePair.getValue()));
        }
    }
    return separatorList;
}

