private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Iterate over each vertex in the subgraph
    for (V vertex : vertices) {
        // Check that the vertex has edges to all other vertices in the subgraph
        for (V otherVertex : vertices) {
            if (vertex != otherVertex && graph.getEdge(vertex, otherVertex) == null) {
                return false;
            }
        }
    }
