public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    FileReader reader = null;
    try {
        reader = new FileReader(file);
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split(",");
            if (parts.length >= 2) {
                long timestamp = Long.parseLong(parts[0]);
                String threadName = parts[1];
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, threadName);
                snapshots.add(snapshot);
            }
        }
        return snapshots;
    }
    finally {
        if (reader != null) {
            reader.close();
        }
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
	List<ThreadSnapshot> threadSnapshots = new ArrayList<>();	
	for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
		String timeRangeStr = timeRange.getTraceNodeTimeFrom() + "-" + timeRange.getTraceNodeTimeTo();
		List<TraceNode> timeRangeTraceNodes = TraceNode.search(file, [concode_field_sep String getTraceNodeTime logClassName concode_field_sep String getTraceNodeSCInfo concode_field_sep String getTraceNodeStatus concode_elem_sep String parseFromFileWithTimeRange concode_elem_sep String traceNodeQuery concode_elem_sep String logStackTraceClass concode_elem_sep String regionName concode_elem_sep String timestamp concode_elem_sep String logLevel concode_elem_sep String stackTraceString concode_elem_sep String actionMsg concode_elem_sep String eventMsg concode_elem_sep String location ]);
		List<ThreadSnapshot> timeRangeThreadSnapshots = new ArrayList<>();
		for (TraceNode traceNode : timeRangeTraceNodes) {
			String threadId = traceNode.getThreadId();
			if (!threadSnapshots.containsKey(threadId)) {
				ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId);
				threadSnapshot.add(traceNode);
				timeRangeThreadSnapshots.add(threadSnapshot);
			} else {
				ThreadSnapshot threadSnapshot = threadSnapshots.get(threadId);
				threadSnapshot.add(traceNode);
			}
		}
		threadSnapshots.addAll(timeRangeThreadSnapshots);
	}
	return threadSnapshots;
}
